           .args(["clippy", "--offline", "--quiet", "--color", "never"])
           .env("CLIPPY_CONF_DIR", &conf)
           .env("CARGO_TARGET_DIR", dir.join("target"))
           .current_dir(dir)
           .output()
           .expect("cargo clippy runs");
       drop(scratch);
       let stderr = String::from_utf8_lossy(&out.stderr);
